// Track recently shown follow-ups to avoid repeats
var _shownFollowUps = [];

window.nachoFollowUps = function(answer) {
    if (!answer) return [];
    var lower = answer.toLowerCase();
    var candidates = [];
    for (var topic in FOLLOW_UPS) {
        if (lower.includes(topic)) {
            candidates = candidates.concat(FOLLOW_UPS[topic]);
        }
    }
    if (candidates.length === 0) {
        // Default follow-ups for any Bitcoin answer
        candidates = ['What is Bitcoin?', 'How do I get started?', 'What is the Lightning Network?', 'Who created Bitcoin?', 'Why is there only 21 million?', 'What is self-custody?'];
    }
    // Filter out recently shown AND recently asked by user
    var _askedRecently = window._nachoAskedQuestions || [];
    var filtered = candidates.filter(function(q) {
        return _shownFollowUps.indexOf(q) === -1 && _askedRecently.indexOf(q.toLowerCase()) === -1;
    });
    if (filtered.length < 3) { _shownFollowUps = []; filtered = candidates.filter(function(q) { return _askedRecently.indexOf(q.toLowerCase()) === -1; }); }
    if (filtered.length === 0) filtered = candidates; // absolute fallback
    // Shuffle and pick 3-5
    filtered.sort(function() { return Math.random() - 0.5; });
    var pickCount = Math.min(Math.max(3, filtered.length), 5);
    var picked = filtered.slice(0, pickCount);
    _shownFollowUps = _shownFollowUps.concat(picked);
    if (_shownFollowUps.length > 30) _shownFollowUps = _shownFollowUps.slice(-15);
    return picked;
};

// ---- Question Analytics ----
window.trackNachoQuestion = function(question, matched) {
    try {
        var analytics = JSON.parse(localStorage.getItem('btc_nacho_analytics') || '[]');
        analytics.push({
            q: question.substring(0, 100),
            matched: matched,
            t: Date.now()
        });
        // Keep last 100
        if (analytics.length > 100) analytics = analytics.slice(-100);
        localStorage.setItem('btc_nacho_analytics', JSON.stringify(analytics));
    } catch(e) {}
};

// ---- Sound Effects ----
let nachoSoundEnabled = localStorage.getItem('btc_nacho_sound') !== 'false';

window.nachoPlaySound = function(type) {
    if (typeof canPlaySound === 'function' && !canPlaySound()) return;
    if (!nachoSoundEnabled) return;
    try {
        var ctx = new (window.AudioContext || window.webkitAudioContext)();
        var osc = ctx.createOscillator();
        var gain = ctx.createGain();
        osc.connect(gain);
        gain.connect(ctx.destination);
        gain.gain.value = 0.08;

        if (type === 'pop') {
            // Short pop for appearing
            osc.frequency.value = 800;
            osc.type = 'sine';
            gain.gain.setValueAtTime(0.08, ctx.currentTime);
            gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.15);
            osc.start(ctx.currentTime);
            osc.stop(ctx.currentTime + 0.15);
        } else if (type === 'coin') {
            // Coin sound for points/trivia
            osc.frequency.value = 1200;
            osc.type = 'sine';
            gain.gain.setValueAtTime(0.06, ctx.currentTime);
            gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.3);
            osc.start(ctx.currentTime);
            osc.stop(ctx.currentTime + 0.3);
            // Second tone
            var osc2 = ctx.createOscillator();
            osc2.connect(gain);
            osc2.frequency.value = 1600;
            osc2.type = 'sine';
            osc2.start(ctx.currentTime + 0.1);
            osc2.stop(ctx.currentTime + 0.3);
        } else if (type === 'click') {
            // Soft click
            osc.frequency.value = 600;
            osc.type = 'triangle';
            gain.gain.setValueAtTime(0.05, ctx.currentTime);
            gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.08);
            osc.start(ctx.currentTime);
            osc.stop(ctx.currentTime + 0.08);
        }
    } catch(e) {}
};

window.toggleNachoSound = function() {
    nachoSoundEnabled = !nachoSoundEnabled;
    localStorage.setItem('btc_nacho_sound', nachoSoundEnabled.toString());
    return nachoSoundEnabled;
};

// ---- Session Context Memory ----
let nachoSessionContext = [];

window.nachoAddContext = function(topic) {
    nachoSessionContext.push(topic);
    if (nachoSessionContext.length > 5) nachoSessionContext.shift();
};

window.nachoGetContext = function() {
    return nachoSessionContext;
};

// Lightning wallet nudge — Nacho suggests connecting a wallet for new signed-in users
setTimeout(function() {
    if (localStorage.getItem('btc_ln_prompt_dismissed') === '1') return;
    var user = typeof currentUser !== 'undefined' ? currentUser : null;
    if (!user || !user.username) return;
    if (user.lightning || user.lightningAddress) return;
    var visited = [];
    try { visited = JSON.parse(localStorage.getItem('btc_visited_channels') || '[]'); } catch(e) {}
    if (visited.length < 5) return; // wait until they've explored a bit
    if (typeof forceShowBubble === 'function') {
        forceShowBubble("⚡ Hey " + (user.username || "friend") + "! Connect a Lightning wallet to tip other users and receive tips! Tap me to learn how. 🦌", function() {
            go('lightning');
        });
        localStorage.setItem('btc_ln_prompt_dismissed', '1');
    }
}, 30000); // show after 30 seconds on page

