for(const cat in NEW_BANK_QUESTIONS) {
    if(QUESTION_BANK[cat]) {
        NEW_BANK_QUESTIONS[cat].forEach(q => {
            if(!QUESTION_BANK[cat].some(p => p.q === q.q)) {
                QUESTION_BANK[cat].push(q);
            }
        });
    } else {
        QUESTION_BANK[cat] = NEW_BANK_QUESTIONS[cat];
    }
}


