    function getDailyFact() {
        var dayOfYear = Math.floor((Date.now() - new Date(new Date().getFullYear(),0,0)) / 86400000);
        return NACHO_DAILY_FACTS[dayOfYear % NACHO_DAILY_FACTS.length];
    }

