(function() {
    function handleHash() {
        var hash = window.location.hash.replace('#', '');
        if (!hash) return;
        console.log('[HASH] Routing to:', hash);
        
        // Wait for app to be ready (up to 8 seconds)
        var maxWait = 8000;
        var waited = 0;
        function tryRoute() {
            if (waited > maxWait) { console.warn('[HASH] Gave up routing to:', hash); return; }
            
            // Wait for DOM essentials
            if (!document.getElementById('msgs') || !document.getElementById('home')) {
                waited += 200;
                setTimeout(tryRoute, 200);
                return;
            }
            
            switch(hash) {
                case 'nacho':
                    if (typeof enterNachoMode === 'function') { enterNachoMode(); return; }
                    break;
                case 'pvp':
                    if (typeof enterPVPMode === 'function') { enterPVPMode(); return; }
                    break;
                case 'forum':
                    if (typeof go === 'function') { go('forum'); return; }
                    break;
                case 'marketplace':
                    if (typeof go === 'function') { go('marketplace'); return; }
                    break;
                case 'first-purchase':
                case 'buy':
                    if (typeof go === 'function') { go('first-purchase'); return; }
                    break;
                case 'trails':
                case 'learn':
                case 'modules':
                    if (typeof go === 'function') { go('trails'); return; }
                    break;
                case 'meetup-builder':
                    if (window._mbRouted) return;
                    if (typeof go === 'function') { window._mbRouted = true; window._skipIRLRules = true; localStorage.setItem('btc_irl_rules_accepted', 'true'); go('irl-sync'); setTimeout(function() { var ro = document.getElementById('irlRulesOverlay'); if (ro) ro.remove(); }, 100); history.replaceState({channel:'meetup-builder'}, '', '#meetup-builder'); var _mbTries2 = 0; var _mbInt2 = setInterval(function() { var ro2 = document.getElementById('irlRulesOverlay'); if (ro2) ro2.remove(); var el = document.getElementById('meetupBuilderSection'); if (el) { clearInterval(_mbInt2); el.scrollIntoView({ behavior: 'smooth', block: 'start' }); } if (++_mbTries2 > 30) clearInterval(_mbInt2); }, 300); return; }
                    break;
                case 'irl-sync':
                case 'meet':
                    if (typeof go === 'function') { go('irl-sync'); return; }
                    break;
                case 'bitcoin-beats':
                    if (typeof go === 'function') { go('bitcoin-beats'); return; }
                    break;
                case 'chat':
                    if (typeof renderChatHub === 'function') { renderChatHub('global'); return; }
                    break;
                case 'dms':
                    if (typeof renderChatHub === 'function') { renderChatHub('dms'); return; }
                    if (typeof openDMInbox === 'function') { openDMInbox(); return; }
                    if (typeof showInbox === 'function') { showInbox(); return; }
                    break;
                case 'lightning':
                    if (typeof go === 'function') { go('lightning'); return; }
                    break;
                case 'dashboard':
                case 'bitcoin-dashboard':
                case 'metrics':
                case 'network':
                    if (typeof toggleDashboard === 'function') { history.replaceState({ home: true }, '', window.location.pathname); toggleDashboard(); return; }
                    break;
                default:
                    // Certificate verification link (e.g. #cert/CERT-XXXXX)
                    if (hash.indexOf('cert/') === 0 && typeof go === 'function') { go(hash); return; }
                    // Channel direct link (e.g. #mining, #self-custody)
                    if (typeof go === 'function' && typeof CHANNELS !== 'undefined' && CHANNELS[hash]) { go(hash); return; }
                    break;
            }
            waited += 200;
            setTimeout(tryRoute, 200);
        }
        // Small initial delay for app to load
        setTimeout(tryRoute, 500);
    }
    
    // Handle on page load
    handleHash();
    
    // Fallback: also try after window.onload in case deferred scripts delayed routing
    window.addEventListener('load', function() {
        setTimeout(function() {
            var h = window.location.hash.replace('#', '');
            // Only re-route if we're still on the home page (hash wasn't consumed)
            if (h && document.getElementById('home') && !document.getElementById('home').classList.contains('hidden')) {
                console.log('[HASH] Post-load fallback routing to:', h);
                handleHash();
            }
        }, 800);
    });
    
    // Handle hash changes while on the page
    window.addEventListener('hashchange', handleHash);
})();

